  } catch (err: unknown) {
    const e = err as { stdout?: Buffer | string; stderr?: Buffer | string; status?: number };
    return {
      stdout: typeof e.stdout === 'string' ? e.stdout : (e.stdout?.toString('utf-8') ?? ''),
      stderr: typeof e.stderr === 'string' ? e.stderr : (e.stderr?.toString('utf-8') ?? ''),
      exitCode: e.status ?? -1,
      durationMs: Date.now() - start,
    };
  }
}

Wire `totem status` into your agent's startup hook so the agent receives the project's live health state before it takes any action:

```text
[Status] Branch: main (dirty)
[Status] Rules: 439 compiled
[Status] Lessons: 1134
[Status] Manifest: fresh
[Status] Shield: stale (code changed since last pass)
```

Example hook for Gemini (`.gemini/hooks/SessionStart.cjs` — the `.cjs` extension is load-bearing: the body is CommonJS, and a repo whose `package.json` declares `"type": "module"` would resolve a bare `.js` as ESM and the hook would throw before emitting the briefing. Note Gemini CLI only executes hooks registered through a `settings.json` `hooks` entry (project, user, or system level — or an extension); there is no filename-convention discovery, so wire the script through one per the vendor's hooks docs):

```javascript
const { spawnSync } = require('child_process');
const run = spawnSync('totem status', {
  shell: true,
  timeout: 20000,
  encoding: 'utf-8',
  stdio: ['ignore', 'pipe', 'pipe'],
});
// The Totem CLI writes its banner to stderr — capture BOTH streams, and emit
// the hookSpecificOutput envelope: interactive Gemini ingests SessionStart
// output ONLY from hookSpecificOutput.additionalContext (plain stdout wraps
// as systemMessage, which the interactive startup consumer never reads).
const briefing = (run.stdout || '') + (run.stderr || '');
process.stdout.write(
  JSON.stringify({
    systemMessage: briefing,
    hookSpecificOutput: { hookEventName: 'SessionStart', additionalContext: briefing },
  }) + '\n',
);
```

The agent now sees whether the manifest is fresh, whether the review stamp is stale, and the current rule and lesson counts before taking any action. (The managed hook `totem init` distributes does exactly this — with `totem describe` + `totem orient --session` as the briefing legs and fail-soft error handling; prefer it over hand-rolling.)

export function bashSpawnEnv(base: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  const { root } = resolveCached();
  if (root === null) {
    return base;
  }
  // root non-null ⟹ win32 resolution: compose a WINDOWS PATH value
  // (`path.win32` flavor + `;` delimiter) regardless of the host running
  // this code — see bashCandidatesUnder.
  const segments = [path.win32.join(root, 'usr', 'bin'), path.win32.join(root, 'bin')];
  const pathKey = Object.keys(base).find((k) => k.toUpperCase() === 'PATH') ?? 'PATH';
  const current = base[pathKey];
  if (current !== undefined && current.length > 0) {
    segments.push(current);
  }
  return { ...base, [pathKey]: segments.join(path.win32.delimiter) };
}

function run(
  cmd: string,
  args: readonly string[],
  opts: { cwd: string },
): { stdout: string; stderr: string } {
  // cross-spawn resolves win32 `.cmd` shims (e.g. `pnpm`) and binaries under
  // paths with spaces WITHOUT a shell, so both platforms spawn the same argv
  // array — no cmd.exe, no manual quoting (repo safe-exec convention). The
  // child-level `timeout` is the ONLY effective bound here: spawnSync blocks
  // the event loop, so vitest's hook/test timeouts cannot fire mid-hang.
  const res = spawnSync(cmd, [...args], {
    cwd: opts.cwd,
    encoding: 'utf-8',
    timeout: INTEGRATION_TIMEOUT_MS,
  });
  if (res.error) {
    throw new Error(`spawn failed for \`${cmd}\`: ${res.error.message}`);
  }
  if (res.status !== 0) {
    throw new Error(
      `\`${cmd} ${args.join(' ')}\` exited ${String(res.status)}\n` +
        `stdout:\n${res.stdout ?? ''}\nstderr:\n${res.stderr ?? ''}`,
    );
  }
  return { stdout: res.stdout ?? '', stderr: res.stderr ?? '' };
}

function run(
  cmd: string,
  args: readonly string[],
  opts: { cwd: string },
): { stdout: string; stderr: string; status: number } {
  // cross-spawn spawns binaries under paths with spaces (node.exe in "Program
  // Files") and win32 `.cmd` shims WITHOUT a shell — same argv array on both
  // platforms, no manual quoting (repo safe-exec convention). The child-level
  // `timeout` is the ONLY effective bound here: spawnSync blocks the event
  // loop, so vitest's test timeout cannot fire while the child hangs.
  const res = spawnSync(cmd, [...args], {
    cwd: opts.cwd,
    encoding: 'utf-8',
    timeout: LITE_BUILD_TIMEOUT_MS,
  });
  if (res.error) {
    throw new Error(`spawn failed for \`${cmd}\`: ${res.error.message}`);
  }
  return {
    stdout: res.stdout ?? '',
    stderr: res.stderr ?? '',
    status: res.status ?? SPAWN_FAILURE_STATUS,
  };
}

