  // "language already registered with a different loader" guard in
  // `registerLang()` doesn't trip on the second extension's registration.
  const tsLoader = () => require.resolve('tree-sitter-typescript/tree-sitter-typescript.wasm');
  const tsxLoader = () => require.resolve('tree-sitter-typescript/tree-sitter-tsx.wasm');
  const jsLoader = () => require.resolve('tree-sitter-javascript/tree-sitter-javascript.wasm');

  registerBuiltinLang('.ts', 'typescript', tsLoader);
  // TypeScript ESM (`.mts`) and CommonJS (`.cts`) are the same grammar as
  // `.ts` — module resolution differs, syntax does not — so they share the
  // '.ts' loader INSTANCE (mmnto-ai/totem#2513). Their absence from the
  // original registry left rules globbing them (compiled rule
  // fea10369daa04c98) able to load but not to run: `extensionToLanguage`
  // returned undefined and `rule-engine.ts` aborted the whole lint the first
  // time a diff carried a `.mts` file.
  registerBuiltinLang('.mts', 'typescript', tsLoader);
  registerBuiltinLang('.cts', 'typescript', tsLoader);
  registerBuiltinLang('.tsx', 'tsx', tsxLoader);
  // TSX grammar handles JSX — same loader instance as '.tsx'.
  registerBuiltinLang('.jsx', 'tsx', tsxLoader);
  registerBuiltinLang('.js', 'javascript', jsLoader);
  registerBuiltinLang('.mjs', 'javascript', jsLoader);
  registerBuiltinLang('.cjs', 'javascript', jsLoader);
}

export function classifyFile(filePath: string): FileClass {
  const basename = path.basename(filePath);

  // 1. Check known filenames first (exact match on basename)
  if (NON_CODE_FILENAMES.has(basename)) return 'NON_CODE';
  if (CODE_FILENAMES.has(basename)) return 'CODE';

  // 2. Check compound extensions before simple extname
  if (hasCompoundNonCodeExtension(filePath)) return 'NON_CODE';

  // 3. Check simple extension
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '') {
    // No extension, not a known filename → fail-closed to CODE
    return 'CODE';
  }

  if (NON_CODE_EXTENSIONS.has(ext)) return 'NON_CODE';
  if (CODE_EXTENSIONS.has(ext)) return 'CODE';

  // 4. Unknown extension → fail-closed to CODE
  return 'CODE';
}

export function checkLanguageGlobConsistency(
  language: string,
  fileGlobs: readonly string[],
): string | null {
  const advice = `§ Design 6 fixes ONE declared language per record — "a multi-language ast-grep rule is N records". Split the rule per language, or correct the glob. (The runtime dispatches ast-grep by FILE EXTENSION, so a scope the declared language does not cover would be evaluated under a grammar the payload was never validated against.)`;
  for (const glob of fileGlobs) {
    const match = TRAILING_EXT_RE.exec(glob);
    if (match === null) {
      return `Prop 310 § Design 6: target.scope.fileGlobs entry '${glob}' carries no file extension, so its scope cannot be pinned to the declared language '${language}'. ${advice}`;
    }
    const extension = `.${match[1]!.toLowerCase()}`;
    const globLanguage = extensionToLanguage(extension);
    if (globLanguage === undefined) {
      return `Prop 310 § Design 6: target.scope.fileGlobs entry '${glob}' targets extension '${extension}', which is not registered, so it cannot be confirmed to match the declared language '${language}'. ${advice}`;
    }
    if (globLanguage !== language) {
      return `Prop 310 § Design 6: target.scope.fileGlobs entry '${glob}' targets language '${globLanguage}' but the record declares '${language}'. ${advice}`;
    }
  }
  return null;
}

