export function extractReviewBodyFindings(
  reviews: Array<{ author: string; body: string }>,
): NormalizedBotFinding[] {
  const findings: NormalizedBotFinding[] = [];
  for (const review of reviews) {
    if (!review.author || !isBotComment(review.author)) continue;

    const tool = detectBot(review.author);
    let parsed: Array<{
      type: 'nitpick' | 'outside-diff' | 'body-only';
      content: string;
      file?: string;
    }> = [];

    if (tool === 'coderabbit') {
      parsed = parseCodeRabbitReviewFindings(review.body);
    } else if (tool === 'greptile') {
      // PROVISIONAL greptile summary parser (mmnto-ai/totem#2192) — see
      // `parseGreptileOutsideDiff`. Refine against a captured live sample.
      parsed = parseGreptileReviewFindings(review.body);
    }

    for (const finding of parsed) {
      findings.push({
        tool,
        // A body-only ("Additional comments") entry carries CR's own severity
        // tag — parse it instead of flattening to a fixed tier (mmnto-ai/totem#2414).
        severity:
          finding.type === 'body-only'
            ? parseSeverityForTool(tool, finding.content)
            : finding.type === 'outside-diff'
              ? 'warning'
              : 'info',
        // Provenance marker (mmnto-ai/totem#2414): dispositions reference
        // `path (outside-diff)` / `path (body-only)` when the section's nested
        // per-file block carried the attribution; the bare `(review body)`
        // fallback stays for unattributed shapes.
        file: finding.file !== undefined ? `${finding.file} (${finding.type})` : '(review body)',
        line: undefined,
        body: finding.content,
        suggestion: undefined,
        resolutionSignal: 'none',
        // No thread reply exists for review-body findings, so no acceptance signal is
        // available — leave `disposition` undefined (the JSDoc contract treats that as
        // "not-declined"), rather than overstating it as `accepted`.
      });

export function evaluateTriageEmptyState(counts: TriageSurfaceCounts): {
  empty: boolean;
  message?: string;
  /** True when raw material existed (→ log visibly), false when the PR was truly bare. */
  surfaced?: boolean;
} {
  const botMaterial = counts.botThreads + counts.bodyFindings + counts.botIssueComments;
  if (botMaterial > 0) return { empty: false };

  const rawFetched = counts.inlineComments + counts.reviews + counts.issueComments;
  if (rawFetched === 0) {
    return {
      empty: true,
      surfaced: false,
      message: 'Nothing to triage — no comments, reviews, or issue-comments on this PR.',
    };
  }
  return {
    empty: true,
    surfaced: true,
    message:
      `Fetched ${counts.inlineComments} inline comment(s), ${counts.reviews} review(s), ` +
      `${counts.issueComments} issue-comment(s) — none from a recognized review bot. ` +
      `Nothing to triage (no bot findings).`,
  };
}

