  split: SplitArtifact,
  effectiveEntries: readonly AuthoringLedgerEntry[],
  verifiedPreWindowPrs: ReadonlySet<number>,
): string[] {
  const trainSet = new Set(split.trainPrs);
  const heldOutSet = new Set(split.heldOutPrs);
