      if (verb[2] === 'refs/heads/2401-done') return '';
      throw Object.assign(new Error(''), { status: 1 });
    }
    throw Object.assign(new Error(`unexpected verb ${verb.join(' ')}`), { status: 1 });
  };

  return { repo, exec };
}

