export function resolveNotApplicableExit(
  reason: string,
  gate: boolean,
  errCtor: new (code: 'SHIELD_FAILED', message: string, hint: string) => Error,
): 0 {
  switch (reason) {
    case 'no-diff':
    case 'all-non-code':
    case 'filtered-empty':
    case 'all-generated':
      return 0;
    default:
      if (gate) {
        throw new errCtor(
          'SHIELD_FAILED',
          `--gate: unknown admission disposition "${reason}" — failing closed (the gate maps only declared dispositions to exits).`,
          'Upgrade @mmnto/cli so the hook and the CLI agree on the disposition vocabulary, or drop --gate for the sensor default.',
        );
      }
      log.warn(
        DISPLAY_TAG,
        `Unknown admission disposition "${reason}" — sensor default exit 0 (a --gate wiring would fail closed here).`,
      );
      return 0;
  }
}

export function runRuleTests(rulesPath: string, testsDir: string): RuleTestSummary {
  const rules = loadCompiledRules(rulesPath);
  // ADR-104 § Convergence — the hooks-surface dispatch lives in CLI's hook
  // test runner (avoids cross-package import from core to the CLI foundation
  // engine). Filter to rules-surface fixtures here so a hooks-surface fixture
  // does not surface as `(unknown — hash X not found in compiled rules)`
  // under `totem rule test`. Defaults to `'rules'` when surface is absent
  // (backwards-compat with fixtures predating the hook engine).
  const fixtures = loadFixtures(testsDir).filter((f) => (f.surface ?? 'rules') === 'rules');

  if (fixtures.length === 0) {
    return { total: 0, passed: 0, failed: 0, skipped: 0, skippedFixtures: [], results: [] };
  }

  const ruleMap = new Map(rules.map((r) => [r.lessonHash, r]));
  const results: RuleTestResult[] = [];
  const skippedFixtures: { path: string; ruleHash: string; ruleHeading: string }[] = [];

  for (const fixture of fixtures) {
    if (isTodoFixture(fixture)) {
      const heading = ruleMap.get(fixture.ruleHash)?.lessonHeading ?? '';
      skippedFixtures.push({
        path: fixture.fixturePath,
        ruleHash: fixture.ruleHash,
        ruleHeading: heading,
      });
      continue;
    }

    const rule = ruleMap.get(fixture.ruleHash);
    if (!rule) {
      results.push({
        ruleHash: fixture.ruleHash,
        ruleHeading: `(unknown — hash ${fixture.ruleHash} not found in compiled rules)`,
        fixturePath: fixture.fixturePath,
        missedFails: fixture.failLines,
        falsePositives: [],
        passed: false,
      });
      continue;
    }

    results.push(testRule(rule, fixture));
  }

  const passed = results.filter((r) => r.passed).length;
  return {
    total: results.length,
    passed,
    failed: results.length - passed,
    skipped: skippedFixtures.length,
    skippedFixtures,
    results,
  };
}

